int score = 85;
if (score >= 90) {
    System.out.println("A");
} else if (score >= 80) {
    System.out.println("B");
} else {
    System.out.println("C");
}

int score = 95;
if (score >= 60) {
    System.out.println("Pass");
} else if (score >= 90) {
    System.out.println("A");
}

if (loggedIn)
    if (admin)
        System.out.println("Admin");
    else
        System.out.println("Not admin");

switch (level) {
    case 1:
        System.out.println("Beginner");
    case 2:
        System.out.println("Intermediate");
}

int i = 5;
while (i < 3) {
    System.out.println(i);
    i++;
}

int i = 5;
do {
    System.out.println(i);
    i++;
} while (i < 3);

String[] names = {"Ann", "Bob"};
for (String name : names) {
    System.out.print(name + " ");
}

int i = 0;
while (i < 3) {
    System.out.println(i);
}

for (int i = 0; i < 5; i++) {
    if (i == 3) {
        break;
    }
    System.out.print(i);
}

for (int i = 0; i < 5; i++) {
    if (i == 2) {
        continue;
    }
    System.out.print(i);
}

int findFirstEven(int[] numbers) {
    for (int n : numbers) {
        if (n % 2 == 0) {
            return n;
        }
    }
    return -1;
}

for (int row = 0; row < 2; row++) {
    for (int col = 0; col < 3; col++) {
        if (col == 1) {
            break;
        }
        System.out.print(row + ":" + col + " ");
    }
}

String status = "NEW";
String label = switch (status) {
    case "NEW" -> "Create";
    case "DONE" -> "Archive";
    default -> "Unknown";
};

String message = switch (code) {
    case 200 -> "OK";
    case 500 -> {
        logError();
        yield "Server error";
    }
    default -> "Unknown";
};

int day = 3;
String label = switch (day) {
    case 1 -> "Monday";
    case 2 -> "Tuesday";
};

outer:
for (int row = 0; row < 3; row++) {
    for (int col = 0; col < 3; col++) {
        if (row == 1 && col == 1) {
            break outer;
        }
    }
}

outer:
for (int row = 0; row < 3; row++) {
    for (int col = 0; col < 3; col++) {
        if (col == 1) {
            continue outer;
        }
    }
}

